"use strict";(globalThis.webpackChunkmiko_docusaurus_en=globalThis.webpackChunkmiko_docusaurus_en||[]).push([[800],{7079(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>r,default:()=>d,frontMatter:()=>a,metadata:()=>i,toc:()=>c});const i=JSON.parse('{"id":"technical-architecture/smart-contracts","title":"Smart Contracts","description":"Miko\'s intelligence stack produces analytical decisions off-chain. These decisions are executed on Robinhood Chain through a set of verified smart contracts and Miko\'s on-chain execution module. This hybrid architecture maximizes off-chain analytical flexibility while ensuring on-chain transparency: every deployed contract is verifiable against its published source code, so any change to on-chain logic is itself public.","source":"@site/docs/technical-architecture/smart-contracts.md","sourceDirName":"technical-architecture","slug":"/technical-architecture/smart-contracts","permalink":"/docs/technical-architecture/smart-contracts","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Smart Contracts"},"sidebar":"tutorialSidebar","previous":{"title":"AI Architecture","permalink":"/docs/technical-architecture/ai-architecture"},"next":{"title":"REST API","permalink":"/docs/technical-architecture/built-with-miko/rest-api"}}');var o=n(4848),s=n(8453);const a={title:"Smart Contracts"},r="On-Chain Implementation on Robinhood Chain",l={},c=[{value:"1. Core On-Chain Contracts",id:"1-core-on-chain-contracts",level:2},{value:"2. On-Chain Execution Module",id:"2-on-chain-execution-module",level:2},{value:"Key Responsibilities:",id:"key-responsibilities",level:3}];function h(e){const t={code:"code",h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",mermaid:"mermaid",p:"p",strong:"strong",ul:"ul",...(0,s.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"on-chain-implementation-on-robinhood-chain",children:"On-Chain Implementation on Robinhood Chain"})}),"\n",(0,o.jsx)(t.p,{children:"Miko's intelligence stack produces analytical decisions off-chain. These decisions are executed on Robinhood Chain through a set of verified smart contracts and Miko's on-chain execution module. This hybrid architecture maximizes off-chain analytical flexibility while ensuring on-chain transparency: every deployed contract is verifiable against its published source code, so any change to on-chain logic is itself public."}),"\n",(0,o.jsx)(t.mermaid,{value:'graph TD\n    subgraph "On-Chain Contracts"\n        A["MIKO Token (ERC-20)<br><i>Fixed Supply & Balance Checkpoints</i>"]\n        H["MikoFeeHook (Uniswap v4)<br><i>4% Swap Tax on the Canonical Pool</i>"] --\x3e B\n        B[("RewardVault<br><i>Treasury, Threshold Claims,<br/>Sleeve Split & Route Verification</i>")]\n        C[("WeeklyRewardController<br><i>Dual Slots: Weekly Core Asset<br/>+ Attention Satellite Asset</i>")]\n        F[("HolderDistributor<br><i>Paginated Pro-Rata Allocation</i>")]\n    end\n    subgraph "Miko\'s Execution Layer"\n        D["On-Chain Execution Module<br><i>Automated Operations</i>"]\n    end\n    subgraph "Workflow"\n        H -- "1#46; Swap Tax Accrues" --\x3e B\n        B -- "2#46; Threshold Reached:<br/>Claim<br/>(25% ops / 75% acquisition,<br/>split core : satellite)" --\x3e D\n        C -- "3#46; Queries Core &<br/>Satellite Asset Addresses" --\x3e D\n        D -- "4#46; Acquires Per Sleeve<br/>(Route Verified On-Chain)" --\x3e F\n        F -- "5#46; Paginated Payout" --\x3e E>"Acquired Assets allocated<br>to <b>Eligible Holders</b>"]\n    end\n    style A fill:#a78bfa,stroke:#6d28d9,color:#fff\n    style H fill:#a78bfa,stroke:#6d28d9,color:#fff\n    style B fill:#c4b5fd,stroke:#6d28d9\n    style C fill:#c4b5fd,stroke:#6d28d9\n    style F fill:#c4b5fd,stroke:#6d28d9\n    style D fill:#93c5fd,stroke:#1d4ed8,color:#000\n    style E fill:#6ee7b7,stroke:#047857'}),"\n",(0,o.jsx)(t.h2,{id:"1-core-on-chain-contracts",children:"1. Core On-Chain Contracts"}),"\n",(0,o.jsx)(t.p,{children:"The on-chain contracts form the foundation of the protocol's trust and security, performing only the minimum necessary functions to reduce the attack surface and increase predictability."}),"\n",(0,o.jsxs)(t.ul,{children:["\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"MIKO Token (ERC-20):"})," The protocol's core asset. The total supply is fixed at deployment with no mint function, and the contract exposes no owner controls over balances, fees, or trading. Every transfer writes a balance checkpoint, giving the protocol an on-chain, manipulation-resistant record of who held what at each allocation snapshot. Protocol accounts (the liquidity position, protocol contracts, and team custody addresses) are excluded from allocations by a list fixed in the constructor. After deployment the list is append-only \u2014 new system accounts can be excluded as the protocol grows, and no exclusion can ever be reversed."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"MikoFeeHook (Uniswap v4 Hook):"})," Enforces the 4% swap tax (",(0,o.jsx)(t.code,{children:"FEE_BPS = 400"}),") on the ETH side of every trade in the canonical MIKO/ETH pool, in both directions, and forwards the proceeds directly to the RewardVault. The steady rate is immutable, wallet-to-wallet transfers are untaxed, and the pool's own LP fee is set to zero, so the stated 4% is the entire trading cost.","\n",(0,o.jsxs)(t.ul,{children:["\n",(0,o.jsxs)(t.li,{children:["\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Anti-Sniping Launch Fee:"})," For launch fairness, a surcharge applies for the first 12 minutes of trading only: it starts at +60% and decays exponentially with a 158-second time constant, making bot sniping at the opening block economically irrational while leaving the steady 4% untouched from minute 12 onward. The surcharge falls below 10% at 4 minutes 43 seconds and cuts to exactly 0 at the 12-minute mark."]}),"\n",(0,o.jsx)(t.mermaid,{value:'xychart-beta\n    title "Anti-sniping surcharge over the first 12 minutes"\n    x-axis ["0:00", "1:00", "2:00", "3:00", "4:00", "4:43", "5:00", "6:00", "7:00", "8:00", "9:00", "10:00", "11:00", "12:00"]\n    y-axis "Surcharge (%)" 0 --\x3e 60\n    line [60, 41.04, 28.07, 19.2, 13.14, 10, 8.99, 6.15, 4.2, 2.88, 1.97, 1.35, 0.92, 0]'}),"\n"]}),"\n"]}),"\n"]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"RewardVault:"})," The protocol treasury. Accrued tax accumulates until it reaches the claim threshold (the value of 500,000 MIKO, roughly 0.05% of supply, converted on-chain at claim time). Each claim splits the accumulated ETH \u2014 25% funds protocol operations, 75% funds acquisition, which is further divided between the core sleeve (weekly selected asset) and the satellite sleeve (community attention leader) at the controller's ratio \u2014 and the vault verifies the execution module's swap route byte-by-byte on-chain before any funds move. Each sleeve's purchase resolves independently, so a delay in one never blocks the other."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"WeeklyRewardController:"})," Stores two asset slots. The ",(0,o.jsx)(t.strong,{children:"core slot"})," holds the weekly selected asset: the execution module applies the AI's routine selection once per weekly cycle, and a separate emergency change (limited to once per cycle) exists to protect holders if a selected asset suffers a sudden critical event such as a rug pull. The ",(0,o.jsx)(t.strong,{children:"satellite slot"})," holds the current community attention leader and can rotate whenever MIKO's evidence gates confirm a genuine leader change. The core/satellite funding ratio can be tuned only within bounds fixed immutably at deployment, and every change to either slot is an on-chain event with full history."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"HolderDistributor:"})," Executes the allocation. Activation, holder-snapshot capture, and payout run as paginated steps, so distribution scales with the holder base. Eligibility (at least $100 of MIKO) is computed on-chain at claim time from a Chainlink ETH/USD feed and the canonical pool's spot price."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"MikoLiquidityVault:"})," Holds the protocol's liquidity position in the canonical pool, locked for 12 months."]}),"\n"]}),"\n",(0,o.jsx)(t.h2,{id:"2-on-chain-execution-module",children:"2. On-Chain Execution Module"}),"\n",(0,o.jsx)(t.p,{children:"Miko's on-chain execution module is the component that converts the AI's analytical decisions into blockchain transactions. It operates as an integrated part of the Miko system, receiving the asset selection directly from the intelligence stack and executing the on-chain operations autonomously."}),"\n",(0,o.jsx)(t.h3,{id:"key-responsibilities",children:"Key Responsibilities:"}),"\n",(0,o.jsxs)(t.ul,{children:["\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Threshold Monitoring and Claiming:"})," Monitors the accumulated tax in the RewardVault and triggers the claim when the threshold is reached."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Swap Execution:"})," Builds the swap routes from the treasury's ETH into the selected assets \u2014 one route per sleeve. Each route is submitted to the RewardVault, which validates it on-chain before execution \u2014 the module cannot redirect funds anywhere the contracts do not allow."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Weekly Selection Application:"})," Applies the intelligence stack's weekly selection to the controller's core slot at the start of each cycle."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Satellite Rotation Application:"})," Applies confirmed attention-leader changes to the controller's satellite slot, exactly as published by the intelligence stack's gated tracking \u2014 strictly ordered, replay-protected, and committed only after on-chain confirmation."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Distribution Paging:"})," Drives the HolderDistributor through its capture and payout pages until every eligible holder is paid."]}),"\n"]}),"\n",(0,o.jsx)(t.p,{children:"The contracts enforce the rules and custody the assets; the module keeps the pipeline running so holders receive their allocations reliably \u2014 claim after claim, week after week \u2014 without anyone needing to press a button."})]})}function d(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(h,{...e})}):h(e)}}}]);